from pathlib import Path

MINI_IP_HTML = r"""<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mini IP</title>
<style>
body{margin:0;background:#08090d;color:#f5f6fa;font:15px system-ui;padding:18px}main{max-width:1100px;margin:auto}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.brand{font-size:28px;font-weight:900}.muted{color:#9299a8}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.card{background:#11141b;border:1px solid #292f3c;border-radius:16px;padding:17px}.wide{grid-column:1/-1}h2{font-size:17px;margin:0 0 12px}.pill{padding:7px 11px;border:1px solid #29303d;border-radius:999px}.ok{color:#67e3a1}.bad{color:#ff667e}input,textarea{width:100%;box-sizing:border-box;background:#090c12;color:white;border:1px solid #303746;border-radius:10px;padding:10px;font:inherit}textarea{min-height:90px}.label{font-size:12px;color:#9299a8;margin:9px 0 5px}button{margin:8px 6px 0 0;padding:10px 13px;border-radius:10px;border:1px solid #303746;background:#191e28;color:white;font-weight:700;cursor:pointer}button.primary{background:#8756ed;border:0}.kv{display:grid;grid-template-columns:150px 1fr;gap:5px 10px;font-size:13px}pre{white-space:pre-wrap;word-break:break-word;background:#090c11;padding:12px;border-radius:10px}.gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:10px}.tile{background:#090c11;border:1px solid #292f3c;border-radius:10px;overflow:hidden}.tile img{width:100%;aspect-ratio:1;object-fit:cover}.tile div{padding:7px;font-size:11px;color:#9299a8}.hero{margin:0 0 14px;padding:24px;border:1px solid #292f3c;border-radius:20px;background:linear-gradient(145deg,#171322,#11141b)}.hero h1{font-size:30px;line-height:1.08;margin:7px 0 10px;max-width:700px}.eyebrow{font-size:11px;letter-spacing:.14em;color:#a98cff;font-weight:800}.hero-actions{display:flex;flex-wrap:wrap;gap:4px;margin-top:18px}.big{padding:13px 16px}.growth-options{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:14px 0}.growth-options button{margin:0;text-align:left;min-height:54px}.growth-options button.selected{outline:2px solid #8756ed;background:#211a31}.growth-status{margin-top:12px;padding:12px;border-radius:12px;background:#090c11;color:#b8bfcc;min-height:20px}.actions{display:flex;flex-wrap:wrap;gap:4px}@media(max-width:720px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}.growth-options{grid-template-columns:1fr 1fr}.hero h1{font-size:25px}}
</style></head><body><main>
<div class="top"><div><div class="brand">MINI IP</div><div class="muted">Создай персонажа → найди его путь → развивай IP</div></div><div id="server" class="pill">ПОДКЛЮЧЕНИЕ…</div></div>
<section class="hero"><div><span class="eyebrow">ПУТЬ ПЕРСОНАЖА</span><h1>Давай найдём, кем станет твой персонаж.</h1><p class="muted">Ты можешь задать направление сам или позволить Mini IP немного поэкспериментировать и найти сильную сторону персонажа.</p></div><div class="hero-actions"><button class="primary big" onclick="showGrowth()">Определить направление</button><button class="big" onclick="startDiscovery()">Найти путь самому</button></div></section>
<div class="grid">
<section class="card wide" id="growth-card"><h2>Направление развития</h2><p class="muted">Это не навсегда. Можно изменить путь в любой момент.</p>
<div id="growth-options" class="growth-options">
<button onclick="chooseGrowth('Популярность')">🌟 Популярность</button><button onclick="chooseGrowth('История и личность')">📖 История и личность</button><button onclick="chooseGrowth('Медиа')">🎬 Медиа</button><button onclick="chooseGrowth('Социальные сети')">📱 Социальные сети</button><button onclick="chooseGrowth('Визуальный IP')">🎨 Визуальный IP</button><button onclick="chooseGrowth('Коммерческий IP')">💼 Коммерческий IP</button><button onclick="chooseGrowth('Голос и выступления')">🎤 Голос и выступления</button><button onclick="chooseGrowth('Эксперимент')">🧪 Эксперимент</button><button onclick="chooseGrowth('Помоги мне выбрать')">✨ Помоги мне выбрать</button></div>
<div class="label">Или расскажи своими словами, каким ты хочешь видеть персонажа</div><textarea id="growth-brief" placeholder="Например: хочу, чтобы Леся стала узнаваемой, интересной и со временем превратилась в коммерческий IP…"></textarea>
<div class="actions"><button class="primary" onclick="saveGrowth()">Сохранить замысел</button><button onclick="startDiscovery()">Пусть Mini IP найдёт путь</button></div>
<div id="growth-status" class="growth-status">Пока направление не выбрано.</div></section>
<section class="card"><h2>1 · Персонаж</h2><div class="label">Имя персонажа</div><input id="name" value="Леся"><div class="label">Главная ДНК / влияние владельца</div><textarea id="dna" placeholder="Характер, стиль, голос, поведение, визуальные особенности…"></textarea><button class="primary" onclick="saveCharacter()">Сохранить персонажа</button><button onclick="randomDNA()">Случайная ДНК</button></section>
<section class="card"><h2>2 · Фабрика контента</h2><div class="label">Сюжет</div><textarea id="brief">Кафе в Москве. Леся с капучино смотрит прямо в камеру. Ложкой размешивает кофе по часовой стрелке и говорит: «Тоже в эту сторону».</textarea><button class="primary" onclick="produce()">Создать контент</button><button onclick="refresh()">Обновить</button><pre id="result">Фабрика готова к работе.</pre></section>
<section class="card" id="photo-card"><h2>3 · Фотография персонажа</h2><p class="muted">Необязательно. Загрузите фото, чтобы сохранить внешний образ и узнаваемость персонажа.</p><input id="photo" type="file" accept="image/jpeg,image/png,image/webp" onchange="previewPhoto()"><div id="photo-preview" style="display:none;margin-top:10px"><img id="photo-img" style="width:100%;max-height:320px;object-fit:contain;border-radius:10px;background:#090c11"></div><button class="primary" onclick="uploadPhoto()">Сохранить фотографию</button><div id="photo-status" class="muted" style="margin-top:8px">Фотография ещё не добавлена.</div></section>
<section class="card wide"><h2>4 · Карточка персонажа</h2><div class="kv"><span>Владелец</span><b id="owner">—</b><span>Персонаж</span><b id="profileName">—</b><span>Материалов</span><b id="count">0</b><span>Последний сигнал</span><b id="signal">—</b><span>Эволюция</span><b id="evolution">—</b></div></section>
<section class="card wide"><h2>5 · Галерея контента</h2><div id="gallery" class="gallery"><span class="muted">Пока пусто.</span></div></section>
<section class="card"><h2>6 · Обучение и сигналы</h2><p class="muted">Результаты циклов сохраняются и используются для следующего решения.</p><button onclick="refresh()">Обновить данные</button></section>
<section class="card"><h2>7 · Эволюция персонажа</h2><p class="muted">После проверенного результата следующий цикл может развивать ДНК персонажа.</p><button class="primary" onclick="produce()">Запустить следующий цикл</button></section>
<section class="card wide"><details><summary>Техническое состояние</summary><pre id="debug">—</pre></details></section>
</div></main>
<script>
let owner=localStorage.mini_ip_owner||'',character=localStorage.mini_ip_character||'',token=localStorage.mini_ip_token||'';
let growth=JSON.parse(localStorage.mini_ip_growth||'null')||{direction:'',brief:'',mode:'',discovery:false,jobs:[]};
function persistGrowth(){localStorage.mini_ip_growth=JSON.stringify(growth)}
function showGrowth(){document.getElementById('growth-card')?.scrollIntoView({behavior:'smooth',block:'start'})}
function chooseGrowth(direction){growth.direction=direction;document.querySelectorAll('#growth-options button').forEach(b=>b.classList.toggle('selected',b.textContent.includes(direction)));$('growth-status').textContent='Выбрано направление: '+direction+'. Можно добавить свой замысел или сразу начать поиск.';persistGrowth()}
async function saveGrowth(){try{await ensureCharacter();growth.brief=$('growth-brief').value.trim();growth.mode='owner-guided';if(!growth.direction)growth.direction='Свободное развитие';persistGrowth();$('growth-status').innerHTML='<span class="ok">✓ Замысел сохранён.</span> Mini IP будет использовать его как ориентир, но направление можно изменить в любой момент.'}catch(e){$('growth-status').textContent=e.message}}
async function startDiscovery(){try{await ensureCharacter();growth.discovery=true;growth.mode='discovery';growth.jobs=[];persistGrowth();$('growth-status').textContent='Mini IP запускает небольшую обкатку: проверяем несколько разных сторон персонажа…';const ideas=[['Повседневность','discovery_daily','Персонаж в простой узнаваемой жизненной ситуации'],['Юмор','discovery_humor','Короткая ироничная ситуация, раскрывающая характер'],['История','discovery_story','Небольшая эмоциональная история персонажа'],['Визуальный образ','discovery_visual','Сильная визуальная сцена для проверки узнаваемости'],['Общение','discovery_social','Ситуация, рассчитанная на реакцию аудитории'],['Неожиданность','discovery_surprise','Необычная ситуация, способная выделить персонажа']];for(const idea of ideas){const brief=(growth.brief?growth.brief+' ':'')+idea[2];const x=await api('/jobs',{method:'POST',body:JSON.stringify({owner_id:owner,character_id:character,platform:'local-test',brief,idea:{mechanic:idea[1],hook:idea[2],brief:brief}})});growth.jobs.push({id:x.job_id,label:idea[0],mechanic:idea[1]})}persistGrowth();$('growth-status').textContent='✓ Обкатка запущена. Mini IP проверяет 6 разных вариантов и будет использовать результаты для следующего решения.';pollDiscovery()}catch(e){$('growth-status').textContent=e.message}}
async function pollDiscovery(){if(!growth.jobs?.length)return;let done=0;for(const j of growth.jobs){try{const x=await api('/jobs/'+j.id);j.status=x.status;if(['SUCCEEDED','DEAD_LETTER','FAILED'].includes(x.status))done++}catch(e){}}persistGrowth();$('growth-status').textContent=done===growth.jobs.length?'✓ Обкатка завершена. Mini IP собрал первый опыт персонажа.':'Идёт обкатка персонажа: '+done+'/'+growth.jobs.length+' экспериментов завершено.';if(done<growth.jobs.length)setTimeout(pollDiscovery,1800);else refresh()}
const $=id=>document.getElementById(id);
function headers(){let h={'Content-Type':'application/json','X-Owner-ID':owner};if(token)h.Authorization='Bearer '+token;return h}
async function api(p,o={}){o.headers=Object.assign(headers(),o.headers||{});let r=await fetch(p,o),x=await r.json().catch(()=>({}));if(r.status===401)throw Error('Требуется ключ доступа');if(!r.ok)throw Error(x.message||x.error||('HTTP '+r.status));return x}
async function auth(){try{let c=await fetch('/config').then(r=>r.json());if(c.auth_required&&!token){token=prompt('Введите токен доступа Mini IP:')||'';localStorage.mini_ip_token=token}if(!owner){let x=await api('/owners',{method:'POST',body:'{}'});owner=x.owner_id;localStorage.mini_ip_owner=owner}await refresh()}catch(e){$('server').textContent='ОШИБКА ДОСТУПА';$('server').className='pill bad';$('debug').textContent=e.message}}
async function ensureCharacter(){if(character)return character;let x=await api('/characters',{method:'POST',body:JSON.stringify({owner_id:owner,name:'Леся',card:{description:'Взрослый вымышленный персонаж; строгий медно-рыжий боб с прямой чёлкой; выразительные зелёно-серые глаза; прямой взгляд; московская визуальная среда; естественная асимметрия 10–15%.',user_controls:{dna_notes:'',voice:{source:'synthetic'}}}})});character=x.character_id;localStorage.mini_ip_character=character;return character}
async function saveCharacter(){try{await ensureCharacter();let x=await api('/characters/'+character+'/preferences',{method:'POST',body:JSON.stringify({owner_id:owner,patch:{dna_notes:$('dna').value,voice:{source:'synthetic',description:'Голосовая ДНК персонажа'}}})});$('result').textContent='Персонаж сохранён · версия '+x.version;await refresh()}catch(e){$('result').textContent=e.message}}
function previewPhoto(){const f=$('photo').files[0];if(!f)return;$('photo-img').src=URL.createObjectURL(f);$('photo-preview').style.display='block';$('photo-status').textContent='Фотография выбрана. Нажмите «Сохранить фотографию».'}
function clearPhoto(){$('photo').value='';$('photo-preview').style.display='none';$('photo-status').textContent='Фотография ещё не добавлена.'}
async function uploadPhoto(){try{await ensureCharacter();const f=$('photo').files[0];if(!f)throw Error('Сначала выберите фотографию');if(!['image/jpeg','image/png','image/webp'].includes(f.type))throw Error('Поддерживаются JPG, PNG и WebP');if(f.size>10*1024*1024)throw Error('Фотография должна быть не больше 10 МБ');let h={'Content-Type':f.type,'X-Owner-ID':owner,'X-Filename':f.name};if(token)h.Authorization='Bearer '+token;let r=await fetch('/characters/'+character+'/reference',{method:'POST',headers:h,body:f}),x=await r.json().catch(()=>({}));if(!r.ok)throw Error(x.message||x.error||('HTTP '+r.status));$('photo-status').textContent='✓ Фотография сохранена и подключена к персонажу';$('photo-status').className='ok';await refresh()}catch(e){$('photo-status').textContent=e.message;$('photo-status').className='bad'}}

async function randomDNA(){try{await ensureCharacter();let x=await api('/characters/'+character+'/randomize-dna',{method:'POST',body:JSON.stringify({owner_id:owner})});let d=(x.card||{}).user_controls?.random_dna||{};$('dna').value=Object.entries(d).map(([k,v])=>k+': '+v).join(', ')}catch(e){$('result').textContent=e.message}}
async function produce(){try{await saveCharacter();let x=await api('/jobs',{method:'POST',body:JSON.stringify({owner_id:owner,character_id:character,platform:'local-test',brief:$('brief').value,idea:{mechanic:'user_brief',hook:$('brief').value,brief:$('brief').value}})});$('result').textContent='В ОЧЕРЕДИ · '+x.job_id;let id=x.job_id,n=0,t=setInterval(async()=>{try{let j=await api('/jobs/'+id);$('result').textContent=({QUEUED:'В ОЧЕРЕДИ',RUNNING:'В РАБОТЕ',SUCCEEDED:'ВЫПОЛНЕНО',DEAD_LETTER:'ОСТАНОВЛЕНО',FAILED:'ОШИБКА'}[j.status]||j.status)+' · '+(j.error||'Цикл выполняется');if(['SUCCEEDED','DEAD_LETTER','FAILED'].includes(j.status)||++n>120){clearInterval(t);refresh()}}catch(e){clearInterval(t);$('result').textContent=e.message}},1500)}catch(e){$('result').textContent=e.message}}
async function refresh(){try{let h=await fetch('/health').then(r=>r.json()),rr=await fetch('/ready'),rd=await rr.json();$('server').textContent=rr.ok?'В СЕТИ':'НЕ ГОТОВ';$('server').className='pill '+(rr.ok?'ok':'bad');if(!owner)return;let s=await api('/status/'+owner),c=(s.characters_detail||[]).find(x=>x.character_id===character)||(s.characters_detail||[])[0];if(c&&!character){character=c.character_id;localStorage.mini_ip_character=character}if(c){$('profileName').textContent=c.name;$('name').value=c.name;$('dna').value=(c.card?.user_controls?.dna_notes)||$('dna').value}let jobs=s.jobs_detail||[],active=jobs.find(j=>['QUEUED','RUNNING'].includes(j.status));$('owner').textContent=owner.slice(0,18)+'…';$('count').textContent=(s.artifacts_detail||[]).length;$('signal').textContent=({QUEUED:'В ОЧЕРЕДИ',RUNNING:'В РАБОТЕ',SUCCEEDED:'ВЫПОЛНЕНО',DEAD_LETTER:'ОСТАНОВЛЕНО',FAILED:'ОШИБКА'}[jobs[0]?.status]||jobs[0]?.status||'—');$('evolution').textContent=active?'Идёт обучение':'Готова к следующему циклу';const ref=(s.artifacts_detail||[]).find(a=>a.character_id===character&&a.variant==='reference');if(ref){$('photo-status').textContent='✓ Фотография персонажа сохранена';$('photo-status').className='ok';} $('debug').textContent=JSON.stringify({health:h,ready:rd,owner,character,jobs:jobs.slice(0,8)},null,2);await gallery(s.artifacts_detail||[])}catch(e){$('debug').textContent=e.message}}
async function gallery(items){if(!items.length){$('gallery').innerHTML='<span class="muted">Пока нет готовых артефактов.</span>';return}$('gallery').innerHTML='';for(const a of items.slice().reverse()){let d=document.createElement('div');d.className='tile';let img=document.createElement('img');try{let r=await fetch('/artifacts/'+a.artifact_id,{headers:headers()});img.src=URL.createObjectURL(await r.blob())}catch(e){}d.appendChild(img);let m=document.createElement('div');m.textContent=({APPROVED:'ГОТОВО',PENDING:'ОЖИДАЕТ',FAILED:'ОШИБКА'}[a.status]||a.status||'')+' · '+(a.variant==='master'?'основной вариант':(a.variant||'материал'));d.appendChild(m);$('gallery').appendChild(d)}}
if(growth.direction){$('growth-status').textContent='Текущее направление: '+growth.direction+(growth.discovery?' · обкатка включена':'');if($('growth-brief'))$('growth-brief').value=growth.brief||''} auth();setInterval(refresh,10000);
</script></body></html>"""

def send_mini_ip(self):
    body = MINI_IP_HTML.encode("utf-8")
    self.send_response(200)
    self.send_header("Content-Type","text/html; charset=utf-8")
    self.send_header("Cache-Control","no-store, no-cache, must-revalidate, max-age=0")
    self.send_header("Content-Length",str(len(body)))
    self.end_headers()
    self.wfile.write(body)
